fn binary_search(v: &Vec<u64>, k: u64) -> usize {
    let mut left = 0usize;
    let mut right = v.len() - 1;

    while left <= right {
        let mid = left + (right - left) / 2;
        let mid_val = v[mid];
        if mid_val == k {
            return mid;
        } else if mid_val < k {
            left = mid + 1;
        } else {
            if mid == 0 {
                break; // To avoid underflow when mid is 0
            }
            right = mid - 1;
        }
    }

    // Since the problem guarantees k appears at least once,
    // the function should never get here.
    // Returning left as a fallback (should not be reached).
    left
}